            or cert.extensions.get_extension_for_class(x509.SubjectAlternativeName).value.get_values_for_type(x509.UniformResourceIdentifier) != [uri]
            or ExtendedKeyUsageOID.SERVER_AUTH not in cert.extensions.get_extension_for_class(x509.ExtendedKeyUsage).value
            or not cert.not_valid_before_utc <= observed < cert.not_valid_after_utc):
        raise ValueError("Actual Node floor certificate binding differs")
    if fresh:
        now = now or datetime.now(timezone.utc)
        if not -CLOCK_SKEW_SECONDS <= (now - observed).total_seconds() <= FRESH_SECONDS:
            raise ValueError("Actual Node floor observation is stale or clock-uncertain")
    signature = value["nodeSignature"]
    if not isinstance(signature, str) or not re.fullmatch(r"[0-9a-f]{128}", signature):
        raise ValueError("Actual Node floor signature differs")
    body = {key: item for key, item in value.items() if key != "nodeSignature"}
    cert.public_key().verify(bytes.fromhex(signature), DOMAIN + floor_canonical(body))

def _atomic(path: Path, data: bytes) -> None:
    temporary = path.with_name(path.name + ".next")
    if temporary.exists() or temporary.is_symlink():
        temporary.unlink()
    descriptor = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    try:
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        if os.name != "nt":
            directory = os.open(path.parent, os.O_RDONLY)
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
    finally:
        if temporary.exists():
            temporary.unlink()


@contextmanager
def _exclusive(path: Path):
    try:
        descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    except FileExistsError:
        raise ValueError("Another leaf rotation writer owns the Node lock") from None
    try:
        os.close(descriptor)
        yield
    finally:
        path.unlink(missing_ok=True)

def prepare_leaf_rotation_batch(args):
    """Issue one shared next CP leaf and exact per-Node public bundles."""
    path, state = args.state, load(args.state)
    active = sorted(active_configured_nodes(state), key=lambda item: item["nodeId"])
    if len(active) < 2:
        raise ValueError("A leaf rotation batch requires at least two active Nodes")
    csrs = {}
    for csr_path in args.csr:
        raw = csr_path.read_bytes()
        node = node_from_csr(state, raw)
        if node["nodeId"] in csrs:
            raise ValueError("Each active Node CSR must be supplied exactly once")
        csrs[node["nodeId"]] = csr_path
    if set(csrs) != {node["nodeId"] for node in active}:
        raise ValueError("The rotation batch must include every active Node")
    output = args.output.resolve()
    with exclusive_file(path / "leaf-rotation.lock"):
        # Every selected member must prove its actual floor matches CP-recorded
        # exact bytes BEFORE any child bundle/publication/journal/CAS mutation.
        observation_dir = getattr(args, "peer_floor_observations", None)
        nonce = getattr(args, "peer_floor_nonce", None)
        if observation_dir is None or not isinstance(nonce, str) or not peer_phase.HEX.fullmatch(nonce):
            raise ValueError("Normal :3 batch requires all actual signed floor files and independent nonce")
        observation_dir = Path(observation_dir)
        if observation_dir.is_symlink() or not observation_dir.is_dir():
            raise ValueError("Actual floor observation directory is unsafe")
        if {p.name for p in observation_dir.iterdir()} != {node["nodeId"] + ".json" for node in active}:
            raise ValueError("Actual floor observation cohort differs")
        floor_observations = {node["nodeId"]: peer_phase.strict(worker_rotation._regular(observation_dir / (node["nodeId"] + ".json"))) for node in active}
        preflight_now = datetime.now(timezone.utc)
        with psycopg.connect(state["adminDSN"]) as conn:
            conn.execute("SELECT set_config('inv.tenant_id',%s,true)", (state["tenantId"],))
            for node in active:
                _plain_cp_floor(path, state, node, _channel_row(conn, state, node), floor_observations[node["nodeId"]], nonce, preflight_now)
        journal = _load_batch_journal(path)
        if output.exists():
            raw, manifest, bundles = _batch_material(output)
            if set(bundles) != set(csrs):
                raise ValueError("Existing rotation batch is not an exact active-Node retry")
            for node_id, csr_path in csrs.items():
                public = csr_public_key(csr_path.read_bytes(), node_id)
                next_node = x509.load_pem_x509_certificate(bundles[node_id][2]["node-cert.pem"])
                if public.public_bytes_raw() != next_node.public_key().public_bytes_raw():
                    raise ValueError("Existing rotation batch CSR binding differs")

