RENEWAL_WINDOW = timedelta(days=2)


def certificate_summary(items, observed_at, *, complete):
    unknown = {
        'state': 'unknown', 'earliestCertificateNotAfter': None,
        'renewalWindowStartsAt': None, 'secondsUntilEarliestExpiry': None,
    }
    if not complete or not items or any(
        item['channelEnabled'] is not True or item['certificateNotAfter'] is None
        for item in items
    ):
        return unknown
    from datetime import datetime

    earliest = min(datetime.fromisoformat(item['certificateNotAfter']) for item in items)
    starts = earliest - RENEWAL_WINDOW
    state = 'expired' if earliest <= observed_at else (
        'renewal-window' if starts <= observed_at else 'ok'
    )
    return {
        'state': state,
        'earliestCertificateNotAfter': earliest.isoformat(),
        'renewalWindowStartsAt': starts.isoformat(),
        'secondsUntilEarliestExpiry': math.floor((earliest - observed_at).total_seconds()),

class NodeTLSClient:
    def __init__(self, *, ca_file, certificate_file, key_file, timeout=40):
        if type(timeout) not in (int, float) or not 0.1 <= timeout <= 40:
            raise DomainError("NODE-0031", "Invalid Node transport timeout", 422)
        try:
            # Build explicit trust without SSLKEYLOGFILE/system trust side effects.
            self.context = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
            self.context.load_verify_locations(cafile=str(ca_file))
            self.context.minimum_version = ssl.TLSVersion.TLSv1_3
            self.context.verify_flags |= ssl.VERIFY_X509_STRICT
            self.context.verify_flags &= ~ssl.VERIFY_X509_PARTIAL_CHAIN
            self.context.load_cert_chain(str(certificate_file), private_key(key_file))
        except (OSError, ValueError, ssl.SSLError):
            raise DomainError(
                "NODE-0031", "Explicit Node TLS credentials unavailable", 503
            ) from None
        self.timeout = timeout

    def exchange(self, channel, permit, *, observation_only=False, cancel_only=False):

def probe(self, channel, request):
